import { useState } from "react";

export const StarRating = ({ totalStars = 5 }) => {
  [starvalue, setstarvalue] = useState(0);
  const handleStar = (value: number) => {
    setstarvalue(value);
  };
  return (
    <div>
      {[...Array(totalStars)].map((_, index) => {
        const StarValue = index + 1;
        return (
          <span key={StarValue} onClick={() => handleStar(StarValue)}>
            *
          </span>
        );
      })}
    </div>
  );
};
